/* Local-only evidence review. Files never leave this browser. Export JSON or use CLI for portable photos. */
'use strict';
const surveyOverlays=new Map([[DAFieldSurvey.datasetId,DAFieldSurvey]]),surveyURLs=new Map();
function surveyOverlay(id){return surveyOverlays.get(id)||null;}
function photoURL(filename){const p=state.data.photos?.find(p=>p.filename===filename);if(!p)return'';return surveyURLs.get(p.id)||(/^data\/photos\/[a-f0-9]+\.(jpe?g|png|webp|heic|heif|tiff?)$/i.test(p.path||'')?p.path:'');}
function photoHTML(filename,large=false){const url=photoURL(filename);return url?`<img class="${large?'evidence-photo':'thumb'}" src="${esc(url)}" alt="Survey photo: ${esc(filename)}" loading="lazy">`:`<span class="${large?'photo-missing':'thumb empty-thumb'}">No photo</span>`;}
function snapPreview(o){if(!Number.isFinite(o.lat)||!Number.isFinite(o.lon))return'<p class="hint">GPS missing. Enter the observation location to see candidate streets.</p>';const xy=c=>[150+(c[0]-o.lon)*111320*Math.cos(o.lat*Math.PI/180)*3,110-(c[1]-o.lat)*111320*3],candidates=o.link.candidates||[];return`<svg class="snap-preview" viewBox="0 0 300 220" role="img" aria-label="Nearby segments, north up; observation in white. Numbers match segment choices."><rect width="300" height="220" fill="#0c1925"/>${candidates.map((c,i)=>{const p=state.data.paths.find(p=>p.id===c.pathId),g=M.geoGeometry(state.data,p),point=xy(c.coordinate);return`<polyline points="${g.map(xy).map(p=>p.join(',')).join(' ')}" fill="none" stroke="${['#67e4ca','#f6cc70','#aeb4ff','#ff91ab','#a3dfff'][i]}" stroke-width="4"/><text x="${point[0]+12}" y="${point[1]-12-i*17}" fill="${['#67e4ca','#f6cc70','#aeb4ff','#ff91ab','#a3dfff'][i]}" font-size="14">${i+1}</text>`;}).join('')}<circle cx="150" cy="110" r="5" fill="white" stroke="#0c1925" stroke-width="2"/><text x="12" y="20" fill="#c5d8e5" font-size="12">N ↑ · nearby street geometry</text></svg><p class="hint">White point = observation. Numbers correspond to segment choices; different sides/approaches need manual review.</p>`;}
async function saveSurvey(overlay){overlay={...overlay,updatedAt:new Date().toISOString()};DASurvey.validate(overlay);const previous=surveyOverlays.get(overlay.datasetId);surveyOverlays.set(overlay.datasetId,overlay);try{if(previous)await DACache.put('survey-previous:'+overlay.datasetId,previous);await DACache.put('survey:'+overlay.datasetId,overlay);}catch{notify('Browser storage unavailable. Export the overlay before closing.');}reloadEvidence();renderSurvey();}
async function importSurveyFiles(files){const revision=state.revision,data=v5raw.get(state.data.id);if(!data.source)throw new Error('Choose a real geography area first');let rows=[],photos=[];for(const f of files.filter(f=>/\.(csv|geojson)$/i.test(f.name)))rows.push(...DASurvey.rowsFrom(await f.text(),f.name));const json=files.find(f=>f.name==='field-survey.json');if(json){const overlay=DASurvey.validate(JSON.parse(await json.text()));if(overlay.datasetId!==data.id)throw new Error('Overlay belongs to another area; select that area first');rows=overlay.observations;photos=overlay.photos;}
 const media=files.filter(f=>/\.(jpe?g|png|heic|heif|webp|tiff?)$/i.test(f.name));if(new Set(media.map(f=>f.name)).size!==media.length)throw new Error('Duplicate photo filenames: rename them first');
 for(const file of media){const buffer=await file.arrayBuffer(),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',buffer))].map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,16),id='PHOTO-'+hash;let meta={};try{meta=await exifr.parse(buffer)||{};}catch{}let matching=rows.filter(o=>o.photoFilename===file.name);if(!matching.length){const o=DASurvey.normalize({photo_filename:file.name},rows.length);rows.push(o);matching=[o];}for(const o of matching){if(o.lat===null&&Number.isFinite(meta.latitude))o.lat=meta.latitude;if(o.lon===null&&Number.isFinite(meta.longitude))o.lon=meta.longitude;if(!o.timestamp&&meta.DateTimeOriginal)o.timestamp=String(meta.DateTimeOriginal instanceof Date?meta.DateTimeOriginal.toISOString():meta.DateTimeOriginal);}
  surveyURLs.set(id,URL.createObjectURL(file));try{await DACache.put('photo:'+id,file);}catch{}photos=photos.filter(p=>p.filename!==file.name);photos.push({id,filename:file.name,path:'data/photos/'+hash+'.'+file.name.split('.').at(-1).toLowerCase(),provenance:'field-observation',gpsSource:Number.isFinite(meta.latitude)?'EXIF':'not present'});
 }
 if(revision!==state.revision)throw new Error('Area or controls changed during import; retry');const previous=surveyOverlay(data.id);if(previous?.observations.length&&!json)throw new Error('An overlay already exists. Export it first, then use Replace survey below to import the complete folder.');const overlay=DASurvey.makeOverlay(rows,data,photos,json?JSON.parse(await json.text()).fixture:false);await saveSurvey(overlay);notify('Survey imported locally. Review types and ambiguous matches below.');
}
function renderSurvey(){if(!$('survey-list'))return;const d=state.data,overlay=surveyOverlay(d.id),observations=d.surveyObservations||[],report=overlay?DASurvey.report({...overlay,observations}):null;$('survey-summary').textContent=report?`${report.observations} observations · ${report.linked} linked · ${report.needsReview} review · ${report.unlinked} unlinked · ${report.unclassified} unclassified · ${report.missingPhotoReferences} missing photos`:'No survey observations yet. Import photos and a CSV, KoBo export, or photos alone.';$('survey-list').innerHTML=observations.map(o=>`<details class="survey-row"><summary>${badge(o.provenance)} ${esc(o.type.replaceAll('_',' '))} · ${esc(o.link.status)} ${o.fixture?'· TEST FIXTURE':''}</summary><div class="survey-review"><div>${photoHTML(o.photoFilename,true)}${snapPreview(o)}</div><form data-observation="${esc(o.id)}"><label>Observation type<select name="type"><option value="unclassified">Choose a type</option>${DASurvey.types.map(t=>`<option value="${t}" ${t===o.type?'selected':''}>${t.replaceAll('_',' ')}</option>`).join('')}</select></label><div class="import-grid"><label>Latitude<input name="lat" type="number" step="any" value="${o.lat??''}"></label><label>Longitude<input name="lon" type="number" step="any" value="${o.lon??''}"></label></div><label>Date/time observed<input name="timestamp" value="${esc(o.timestamp)}" placeholder="Unknown if omitted"></label><label>Measurement<input name="measurement" value="${esc(o.measurement)}" placeholder="e.g. clear width 75 cm"></label><label>Note<textarea name="note">${esc(o.note)}</textarea></label><label>Street / side at intersections<select name="targetPathId"><option value="">Automatic (20 metre maximum)</option>${(o.link.candidates||[]).map((c,i)=>{const path=d.paths.find(p=>p.id===c.pathId);return`<option value="${esc(c.pathId)}" ${o.targetPathId===c.pathId?'selected':''}>${i+1}. ${esc(path?.tags?.name||'Unnamed segment')} · ${c.distanceMeters.toFixed(1)} m · ${esc(path?.tags?.highway||'path')}</option>`;}).join('')}</select></label><p class="hint">${esc(o.link.reason||o.link.method)}. A photo alone does not establish a whole stretch as step-free. Check the linked segment end to end.</p><button type="submit">Save observation</button></form></div></details>`).join('');for(const form of $('survey-list').querySelectorAll('form'))form.onsubmit=async e=>{e.preventDefault();try{const o=overlay.observations.find(x=>x.id===form.dataset.observation);const copy={...o};for(const key of ['type','timestamp','note','measurement','targetPathId'])copy[key]=form.querySelector(`[name="${key}"]`).value;for(const key of ['lat','lon']){const value=form.querySelector(`[name="${key}"]`).value;copy[key]=value===''?null:Number(value);}copy.targetWayId='';copy.link=DASurvey.snap(copy,v5raw.get(d.id));await saveSurvey({...overlay,observations:overlay.observations.map(x=>x.id===copy.id?copy:x)});}catch(error){notify(error.message);}};
 $('survey-conflicts').innerHTML=(d.evidenceConflicts||[]).map(c=>`<p class="error">${esc(c.reason)} · ${esc(c.observationId)}</p>`).join('');
}
function setupSurveyUI(){const section=document.createElement('section');section.innerHTML=`<h3>Local photo survey</h3><p class="hint">Your photos stay on this computer. Include confirmed step-free stretches as well as barriers. Unlinked observations remain in this review list and, when GPS exists, on the map.</p><label>Import a folder<input id="survey-folder" type="file" multiple webkitdirectory></label><label>Or select CSV / GeoJSON / photos / field-survey.json<input id="survey-files" type="file" multiple accept=".csv,.geojson,.json,image/*"></label><div class="inline-actions"><button id="export-survey">Export field-survey.json</button><button id="replace-survey">Replace survey (clear local overlay)</button><button id="undo-survey">Undo last survey change</button></div><p id="survey-summary" class="hint"></p><div id="survey-conflicts"></div><div id="survey-list"></div>`;$('pane-import').prepend(section);for(const id of ['survey-folder','survey-files'])$(id).onchange=async e=>{try{await importSurveyFiles([...e.target.files]);}catch(error){notify(error.message);}finally{e.target.value='';}};$('export-survey').onclick=()=>{const overlay=surveyOverlay(state.data.id);if(!overlay){notify('Import survey data first');return;}const blob=new Blob([JSON.stringify(overlay,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='field-survey.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('JSON exported. Keep the original photos; CLI creates the portable data/photos folder.');};$('undo-survey').onclick=async()=>{try{const previous=await DACache.get('survey-previous:'+state.data.id);if(previous)await saveSurvey(previous);else notify('No earlier local survey saved');}catch(e){notify(e.message);}};$('replace-survey').onclick=()=>saveSurvey(DASurvey.makeOverlay([],v5raw.get(state.data.id)));}
